const CSS=".card {\n  box-sizing: border-box;\n  width: 100%;\n  height: 100%;\n  padding: 8px;\n  display: flex;\n  flex-direction: column;\n  gap: 6px;\n  min-width: 0;\n  min-height: 0;\n  overflow: hidden;\n  color: var(--ink);\n  font: 13px/1.35 system-ui, -apple-system, \"PingFang SC\", \"Microsoft YaHei\", sans-serif;\n}\n.card *, .card *::before, .card *::after { box-sizing: border-box; }\n\n.body { flex: 1; min-height: 0; min-width: 0; display: flex; flex-direction: column; gap: 8px; }\n.form, .results { display: flex; flex-direction: column; gap: 4px; min-width: 0; min-height: 0; }\n.form { flex: none; overflow: auto; }\n.results { flex: 1; gap: 6px; }\n\n/* \u9876\u90e8\u6807\u7b7e\uff08\u4ec5 194\u00d7194\uff09 */\n.tabs { flex: none; display: flex; gap: 4px; padding: 2px; border-radius: 9px; background: var(--soft); }\n.tab { flex: 1; height: 22px; border: 0; border-radius: 7px; background: transparent; color: var(--muted); font: inherit; font-size: 11.5px; cursor: pointer; }\n.tab[aria-selected=\"true\"] { background: var(--panel-paper); color: var(--ink); font-weight: 600; }\n\n.hd { display: flex; align-items: center; gap: 6px; font-weight: 700; font-size: 14px; flex: none; }\n.dot { width: 8px; height: 8px; border-radius: 50%; background: var(--accent); flex: none; }\n\n/* \u8f93\u5165 */\n.fld { display: flex; align-items: center; gap: 6px; height: 28px; padding: 0 8px; min-width: 0; border: 1px solid var(--line); border-radius: 8px; background: var(--panel-paper); }\n.fld:focus-within { outline: 2px solid var(--accent); outline-offset: -1px; }\n.fld span { flex: none; font-size: 11px; color: var(--muted); }\n.in, .sel { flex: 1; min-width: 0; width: 100%; height: 100%; border: 0; outline: none; background: transparent; color: var(--ink); font: inherit; font-size: 12.5px; padding: 0; }\n.in::placeholder { color: var(--muted); }\n.sel option { background: var(--panel-paper); color: var(--ink); }\n.row2 { display: grid; grid-template-columns: minmax(0, 1fr) 64px; gap: 4px; }\n.row2 .fld { padding: 0 4px 0 6px; }\n\n.go { flex: none; height: 32px; border: 0; border-radius: 10px; background: var(--accent); color: var(--on-accent); font: inherit; font-weight: 600; cursor: pointer; }\n.go:active { opacity: .85; }\n\n.notice { font-size: 11px; line-height: 1.35; padding: 4px 7px; border-radius: 8px; background: var(--soft); color: var(--ink); flex: none; }\n.notice.err { border: 1px solid var(--accent); font-weight: 600; }\n\n/* \u7ed3\u679c */\n.rh { flex: none; display: flex; align-items: center; gap: 4px; }\n.rh h3 { flex: 1; margin: 0; font-size: 12px; font-weight: 700; white-space: nowrap; }\n.btn { height: 24px; padding: 0 8px; border: 1px solid var(--line); border-radius: 8px; background: var(--button-paper, var(--panel-paper)); color: var(--ink); font: inherit; font-size: 11.5px; white-space: nowrap; cursor: pointer; }\n.list { flex: 1; min-height: 0; min-width: 0; overflow: auto; display: flex; flex-direction: column; gap: 6px; }\n.empty { padding: 8px; font-size: 11.5px; color: var(--muted); border: 1px dashed var(--line); border-radius: 10px; }\n.item { flex: none; display: flex; flex-direction: column; gap: 4px; padding: 6px 8px; border: 1px solid var(--line); border-radius: 10px; background: var(--panel-paper); }\n.ta { display: block; width: 100%; min-height: 40px; padding: 0; border: 0; outline: none; resize: none; background: transparent; color: var(--ink); font: inherit; font-size: 13px; font-weight: 600; line-height: 1.4; field-sizing: content; }\n.ta::placeholder { color: var(--muted); font-weight: 400; }\n.meta { display: flex; align-items: center; justify-content: space-between; gap: 6px; font-size: 11px; color: var(--muted); }\n.meta .btn { height: 22px; font-size: 11px; }\n.cnt.over { color: var(--accent); font-weight: 700; }\n\n/* 404\u00d7194\uff1a\u5de6\u8bbe\u7f6e\u53f3\u7ed3\u679c */\n.card[data-size=\"6x3\"] .body { flex-direction: row; }\n.card[data-size=\"6x3\"] .form { width: 188px; }\n.card[data-size=\"6x3\"] .results { flex: 1; }\n\n/* 194\u00d7404\uff1a\u4e0a\u4e0b\u6392\u5217 */\n.card[data-size=\"3x6\"] .form { overflow: visible; }\n\n/* 404\u00d7404\uff1a\u5bbd\u677e\u4e24\u5217\u8868\u5355 */\n.card[data-size=\"6x6\"] { padding: 12px; gap: 8px; }\n.card[data-size=\"6x6\"] .form { display: grid; grid-template-columns: 1fr 1fr; gap: 6px; overflow: visible; }\n.card[data-size=\"6x6\"] .hd { grid-column: 1 / -1; font-size: 15px; }\n.card[data-size=\"6x6\"] .row2, .card[data-size=\"6x6\"] .go, .card[data-size=\"6x6\"] .notice { grid-column: 1 / -1; }\n.card[data-size=\"6x6\"] .row2 { grid-template-columns: minmax(0, 1fr) 90px; gap: 6px; }\n.card[data-size=\"6x6\"] .fld { height: 32px; }\n.card[data-size=\"6x6\"] .go { height: 36px; }\n.card[data-size=\"6x6\"] .ta { font-size: 14px; }\n";
const TONES = ['种草安利', '干货教程', '搞笑轻松', '情绪共鸣', '专业严谨', '悬念好奇'];
const COUNTS = [3, 5, 8, 10];
const LIMIT = 20;

function normCfg(c) {
  c = c || {};
  const n = Number(c.count);
  return {
    topic: typeof c.topic === 'string' ? c.topic : '',
    audience: typeof c.audience === 'string' ? c.audience : '',
    tone: TONES.indexOf(c.tone) >= 0 ? c.tone : TONES[0],
    count: COUNTS.indexOf(n) >= 0 ? n : 5
  };
}

function charLen(t) {
  return Array.from(t || '').length;
}

// 把界面里尚未保存的设置和标题草稿合并进最新的持久数据
function snap(s, c, d) {
  const base = normCfg(s.cfg);
  const list = (Array.isArray(s.titles) ? s.titles : []).map(function (t) {
    return d[t.id] !== undefined ? Object.assign({}, t, { text: d[t.id] }) : t;
  });
  return Object.assign({}, s, { cfg: Object.assign(base, c), titles: list });
}


function mount(ctx) {
  const { root, el, state, ui, commit, redraw, uid } = ctx;
  const size = ctx.size || root.getAttribute('data-size') || '6x6';
  if (!ui.cfg) ui.cfg = normCfg(state.cfg);
  if (!ui.drafts) ui.drafts = {};
  if (!ui.tab) ui.tab = 'form';
  const cfg = ui.cfg;
  const titles = Array.isArray(state.titles) ? state.titles : [];

  function save(extra, nextUi) {
    const c = Object.assign({}, ui.cfg);
    const d = Object.assign({}, ui.drafts);
    return commit(function (s) {
      const n = snap(s, c, d);
      return extra ? extra(n) : n;
    }, Object.assign({}, ui, { drafts: {}, dirty: false }, nextUi || {})).catch(function () {
      ui.notice = { err: true, where: 'form', text: '保存失败，请重试。' };
      redraw();
    });
  }

  function persistSoon() {
    setTimeout(function () {
      if (!ui.dirty) return;
      try {
        const ae = root.getRootNode().activeElement;
        if (ae && root.contains(ae)) return;
      } catch (e) {}
      save();
    }, 300);
  }

  // 平台没有 AI 推理接口：只保存设置并如实说明，不编造标题
  function noAi(kind) {
    if (kind === 'gen' && !cfg.topic.trim()) {
      ui.notice = { err: true, where: 'form', text: '请先填写主题再生成。' };
      redraw();
      return;
    }
    save(null, {
      notice: kind === 'gen'
        ? { where: 'form', text: 'AI 生成暂未接入，设置已保存。' }
        : { where: 'results', text: 'AI 换一批暂未接入，现有标题不变。' }
    });
  }

  function addManual() {
    const id = uid();
    save(function (n) {
      return Object.assign(n, { titles: [{ id: id, text: '' }].concat(n.titles) });
    }, { focusId: id, notice: null });
  }

  function removeTitle(id) {
    save(function (n) {
      return Object.assign(n, { titles: n.titles.filter(function (x) { return x.id !== id; }) });
    }, { notice: null });
  }

  function switchTab(k) {
    if (ui.dirty) save(null, { tab: k });
    else { ui.tab = k; redraw(); }
  }

  function noticeEl(n) {
    return el('div', { class: 'notice' + (n.err ? ' err' : ''), role: 'status' }, (n.err ? '！' : '提示：') + n.text);
  }

  function field(label, key, ph) {
    const inp = el('input', {
      class: 'in', type: 'text', value: cfg[key], placeholder: ph, maxlength: 60, 'aria-label': label,
      oninput: function (e) { ui.cfg[key] = e.target.value; ui.dirty = true; },
      onblur: persistSoon,
      onkeydown: function (e) {
        if (key === 'topic' && e.key === 'Enter') { e.preventDefault(); noAi('gen'); }
      }
    });
    inp.value = cfg[key];
    return el('label', { class: 'fld' }, el('span', {}, label), inp);
  }

  function select(opts, val, label, onch) {
    const s = el('select', { class: 'sel', 'aria-label': label, title: label, onchange: onch },
      ...opts.map(function (o) { return el('option', { value: String(o.v) }, o.t); }));
    s.value = String(val);
    return el('div', { class: 'fld' }, s);
  }

  function form() {
    const kids = [];
    if (size === '3x6' || size === '6x6') {
      kids.push(el('div', { class: 'hd' }, el('span', { class: 'dot' }), '小红书标题生成'));
    }
    kids.push(field('主题', 'topic', '这篇笔记写什么'));
    kids.push(field('人群', 'audience', '想给谁看'));
    kids.push(el('div', { class: 'row2' },
      select(TONES.map(function (t) { return { v: t, t: t }; }), cfg.tone, '语气', function (e) {
        ui.cfg.tone = e.target.value; save();
      }),
      select(COUNTS.map(function (n) { return { v: n, t: n + ' 个' }; }), cfg.count, '数量', function (e) {
        ui.cfg.count = Number(e.target.value); save();
      })));
    kids.push(el('button', { class: 'go', type: 'button', onclick: function () { noAi('gen'); } },
      '生成 ' + cfg.count + ' 个标题'));
    if (ui.notice && ui.notice.where === 'form') kids.push(noticeEl(ui.notice));
    return el('section', { class: 'form' }, ...kids);
  }

  function item(t) {
    const text = ui.drafts[t.id] !== undefined ? ui.drafts[t.id] : (t.text || '');
    const cnt = el('span', { class: 'cnt' });
    function paint(v) {
      const n = charLen(v);
      cnt.textContent = n > LIMIT ? '超出 ' + n + '/' + LIMIT + ' 字' : n + '/' + LIMIT + ' 字';
      cnt.className = n > LIMIT ? 'cnt over' : 'cnt';
    }
    const ta = el('textarea', {
      class: 'ta', rows: 2, placeholder: '输入标题', 'aria-label': '标题内容',
      oninput: function (e) { ui.drafts[t.id] = e.target.value; ui.dirty = true; paint(e.target.value); },
      onblur: persistSoon
    });
    ta.value = text;
    paint(text);
    if (ui.focusId === t.id) {
      setTimeout(function () { try { ta.focus(); } catch (e) {} }, 0);
      ui.focusId = null;
    }
    return el('div', { class: 'item' }, ta,
      el('div', { class: 'meta' }, cnt,
        el('button', { class: 'btn', type: 'button', onclick: function () { removeTitle(t.id); } }, '删除')));
  }

  function results() {
    const kids = [
      el('div', { class: 'rh' },
        el('h3', {}, '标题 ' + titles.length),
        el('button', { class: 'btn', type: 'button', onclick: addManual }, '手写一条'),
        el('button', { class: 'btn', type: 'button', onclick: function () { noAi('swap'); } }, '换一批'))
    ];
    if (ui.notice && ui.notice.where === 'results') kids.push(noticeEl(ui.notice));
    kids.push(el('div', { class: 'list' },
      ...(titles.length
        ? titles.map(item)
        : [el('div', { class: 'empty' },
            '还没有标题。AI 生成暂未接入（平台没有 AI 推理接口），不会编造示例。可以先点「手写一条」，写下的标题都能直接修改。')])));
    return el('section', { class: 'results' }, ...kids);
  }

  function tab(k, text) {
    return el('button', {
      class: 'tab', type: 'button', role: 'tab', 'aria-selected': String(ui.tab === k),
      onclick: function () { switchTab(k); }
    }, text);
  }

  if (size === '3x3') {
    root.append(
      el('div', { class: 'tabs', role: 'tablist' }, tab('form', '设置'), tab('res', '标题 ' + titles.length)),
      el('div', { class: 'body' }, ui.tab === 'res' ? results() : form()));
  } else {
    root.append(el('div', { class: 'body' }, form(), results()));
  }
}

